def R(has, prop=None, value=None, msg=None):
    c = {"check": "rule", "has": has}
    if prop:
        c["prop"] = prop
    if value is not None:
        c["value"] = value
    c["msg"] = msg or [f"В стилях есть правило для {has}" + (f" со свойством {prop}" if prop else ""),
                       f"Стильдерде {has} үшін ереже бар" + (f" ({prop} қасиетімен)" if prop else "")]
    return c


def M(text="max-width", prop=None, msg=None):
    c = {"check": "media", "text": text}
    if prop:
        c["prop"] = prop
    c["msg"] = msg or [f"Есть правило @media ({text})" + (f" со свойством {prop}" if prop else ""),
                       f"@media ({text}) ережесі бар" + (f" ({prop} қасиетімен)" if prop else "")]
    return c


def K(msg=None):
    return {"check": "keyframes", "msg": msg or ["Есть анимация @keyframes", "@keyframes анимациясы бар"]}


